1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
11	type Project = {
12	  id: number;
13	  name: string;
14	  clientId: number;
15	  clientName: string;
16	  archived: boolean;
17	  status: ProjectStatus;
18	};
19	type Invoice = {
20	  id: number;
21	  projectId: number;
22	  amount: number;
23	  amountDue: number;
24	  status: string;
25	  issuedDate: string;
26	  dueDate: string;
27	};
28	type Task = { id: number; projectId: number; title: string; done: boolean };
29	type Tag = { id: number; name: string };
30	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
31	
32	type LineItem = {
33	  id: number;
34	  invoiceId: number;
35	  description: string;
36	  qty: number;
37	  unitPrice: number;
38	};
39	
40	type Payment = { id: number; invoiceId: number; amount: number; date: string };
41	
42	function money(amount: number): string {
43	  return `$${Number(amount).toFixed(2)}`;
44	}
45	
46	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
47	// readable at a glance.
48	function moneyGrouped(amount: number): string {
49	  return `$${Number(amount).toLocaleString('en-US', {
50	    minimumFractionDigits: 2,
51	    maximumFractionDigits: 2,
52	  })}`;
53	}
54	
55	type ProjectBudget = { budget: number | null; invoiced: number; remaining: number | null };
56	
57	// One charge line while it is being edited on screen: the fields are held as raw strings so the
58	// inputs stay controlled and the total can recompute live as they change.
59	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
60	
61	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
62	// many, price each), the total worked out for you, and a form to add another line. Each line can be
63	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
64	// own line-item state, scoped to the one invoice it is showing.
65	function InvoiceDetail({
66	  invoiceId,
67	  onChange,
68	  onClose,
69	}: {
70	  invoiceId: number;
71	  onChange: () => void;
72	  onClose: () => void;
73	}) {
74	  const [items, setItems] = useState<EditItem[]>([]);
75	  const [description, setDescription] = useState('');
76	  const [qty, setQty] = useState('');
77	  const [unitPrice, setUnitPrice] = useState('');
78	  const [payments, setPayments] = useState<Payment[]>([]);
79	  const [paymentAmount, setPaymentAmount] = useState('');
80	  const [paymentDate, setPaymentDate] = useState('');
81	  const [status, setStatus] = useState('');
82	
83	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
84	  // a payment is added rather than flipping it by hand.
85	  async function loadStatus() {
86	    const res = await fetch(`/api/invoices/${invoiceId}`);
87	    const inv: Invoice = await res.json();
88	    setStatus(inv.status);
89	  }
90	
91	  async function load() {
92	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
93	    const rows: LineItem[] = await res.json();
94	    setItems(
95	      rows.map((li) => ({
96	        id: li.id,
97	        description: li.description,
98	        qty: String(li.qty),
99	        unitPrice: String(li.unitPrice),
100	      })),
101	    );
102	  }
103	
104	  async function loadPayments() {
105	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
106	    setPayments(await res.json());
107	  }
108	
109	  async function submitPayment(e: React.FormEvent) {
110	    e.preventDefault();
111	    const value = Number(paymentAmount);
112	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
113	      return;
114	    }
115	    if (paymentDate.trim() === '') {
116	      return;
117	    }
118	    await fetch(`/api/invoices/${invoiceId}/payments`, {
119	      method: 'POST',
120	      headers: { 'Content-Type': 'application/json' },
121	      body: JSON.stringify({ amount: value, date: paymentDate }),
122	    });
123	    setPaymentAmount('');
124	    setPaymentDate('');
125	    await loadPayments();
126	    await loadStatus();
127	    onChange();
128	  }
129	
130	  useEffect(() => {
131	    void load();
132	    void loadPayments();
133	    void loadStatus();
134	  }, [invoiceId]);
135	
136	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
137	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
138	  }
139	
140	  function amountOf(li: EditItem): number {
141	    const line = Number(li.qty) * Number(li.unitPrice);
142	    return Number.isFinite(line) ? line : 0;
143	  }
144	
145	  async function save(li: EditItem) {
146	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
147	      return;
148	    }
149	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
150	      method: 'POST',
151	      headers: { 'Content-Type': 'application/json' },
152	      body: JSON.stringify({
153	        description: li.description,
154	        qty: Number(li.qty),
155	        unitPrice: Number(li.unitPrice),
156	      }),
157	    });
158	    await load();
159	    onChange();
160	  }
161	
162	  async function remove(id: number) {
163	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
164	    await load();
165	    onChange();
166	  }
167	
168	  async function submit(e: React.FormEvent) {
169	    e.preventDefault();
170	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
171	      return;
172	    }
173	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
174	      method: 'POST',
175	      headers: { 'Content-Type': 'application/json' },
176	      body: JSON.stringify({
177	        description,
178	        qty: Number(qty),
179	        unitPrice: Number(unitPrice),
180	      }),
181	    });
182	    setDescription('');
183	    setQty('');
184	    setUnitPrice('');
185	    await load();
186	    onChange();
187	  }
188	
189	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
190	
191	  return (
192	    <section data-testid="invoice-detail">
193	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
194	        Back to invoices
195	      </button>
196	
197	      <p data-testid="invoice-status">{status}</p>
198	
199	      <table data-testid="invoice-lineitems-table">
200	        <tbody>
201	          {items.map((li) => (
202	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
203	              <td>
204	                <input
205	                  data-testid="lineitem-description"
206	                  value={li.description}
207	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
208	                />
209	              </td>
210	              <td>
211	                <input
212	                  data-testid="lineitem-qty"
213	                  value={li.qty}
214	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
215	                />
216	              </td>
217	              <td>
218	                <input
219	                  data-testid="lineitem-unitprice"
220	                  value={li.unitPrice}
221	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
222	                />
223	              </td>
224	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
225	              <td>
226	                <button
227	                  data-testid={`lineitem-save-${li.id}`}
228	                  type="button"
229	                  onClick={() => save(li)}
230	                >
231	                  Save
232	                </button>
233	                <button
234	                  data-testid={`lineitem-remove-${li.id}`}
235	                  type="button"
236	                  onClick={() => remove(li.id)}
237	                >
238	                  Remove
239	                </button>
240	              </td>
241	            </tr>
242	          ))}
243	        </tbody>
244	      </table>
245	
246	      <p data-testid="invoice-amount">{money(total)}</p>
247	
248	      <form data-testid="lineitem-form" onSubmit={submit}>
249	        <input
250	          data-testid="lineitem-form-description"
251	          placeholder="Description"
252	          value={description}
253	          onChange={(e) => setDescription(e.target.value)}
254	        />
255	        <input
256	          data-testid="lineitem-form-qty"
257	          placeholder="How many"
258	          value={qty}
259	          onChange={(e) => setQty(e.target.value)}
260	        />
261	        <input
262	          data-testid="lineitem-form-unitprice"
263	          placeholder="Price each"
264	          value={unitPrice}
265	          onChange={(e) => setUnitPrice(e.target.value)}
266	        />
267	        <button data-testid="lineitem-form-submit" type="submit">
268	          Add line item
269	        </button>
270	      </form>
271	
272	      <table data-testid="invoice-payments-table">
273	        <tbody>
274	          {payments.map((p) => (
275	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
276	              <td data-testid="payment-amount">{money(p.amount)}</td>
277	              <td data-testid="payment-date">{p.date}</td>
278	            </tr>
279	          ))}
280	        </tbody>
281	      </table>
282	
283	      <form data-testid="payment-form" onSubmit={submitPayment}>
284	        <input
285	          data-testid="payment-form-amount"
286	          placeholder="Amount paid"
287	          value={paymentAmount}
288	          onChange={(e) => setPaymentAmount(e.target.value)}
289	        />
290	        <input
291	          data-testid="payment-form-date"
292	          type="date"
293	          value={paymentDate}
294	          onChange={(e) => setPaymentDate(e.target.value)}
295	        />
296	        <button data-testid="payment-form-submit" type="submit">
297	          Record payment
298	        </button>
299	      </form>
300	    </section>
301	  );
302	}
303	
304	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
305	// own invoice state, scoped to the one project it is showing.
306	function ProjectDetail({ project }: { project: Project }) {
307	  const [invoices, setInvoices] = useState<Invoice[]>([]);
308	  const [tasks, setTasks] = useState<Task[]>([]);
309	  const [tags, setTags] = useState<Tag[]>([]);
310	  const [allTags, setAllTags] = useState<Tag[]>([]);
311	  const [tagToAdd, setTagToAdd] = useState('');
312	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
313	  const [amount, setAmount] = useState('');
314	  const [amountError, setAmountError] = useState('');
315	  const [sortByDue, setSortByDue] = useState(false);
316	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
317	  const [notes, setNotes] = useState<Note[]>([]);
318	  const [noteText, setNoteText] = useState('');
319	  const [budget, setBudget] = useState<ProjectBudget | null>(null);
320	  const [budgetInput, setBudgetInput] = useState('');
321	
322	  async function loadBudget() {
323	    const res = await fetch(`/api/projects/${project.id}/budget`);
324	    setBudget(await res.json());
325	  }
326	
327	  async function load() {
328	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
329	    setInvoices(await res.json());
330	    // Invoiced (and so remaining) is derived from the project's invoices, so re-read the budget
331	    // picture whenever the invoices change.
332	    await loadBudget();
333	  }
334	
335	  async function submitBudget(e: React.FormEvent) {
336	    e.preventDefault();
337	    const value = Number(budgetInput);
338	    if (budgetInput.trim() === '' || !Number.isFinite(value) || value < 0) {
339	      return;
340	    }
341	    await fetch(`/api/projects/${project.id}/budget`, {
342	      method: 'POST',
343	      headers: { 'Content-Type': 'application/json' },
344	      body: JSON.stringify({ budget: value }),
345	    });
346	    setBudgetInput('');
347	    await loadBudget();
348	  }
349	
350	  async function loadNotes() {
351	    const res = await fetch(`/api/notes?targetType=project&targetId=${project.id}`);
352	    setNotes(await res.json());
353	  }
354	
355	  async function submitNote(e: React.FormEvent) {
356	    e.preventDefault();
357	    if (!noteText.trim()) {
358	      return;
359	    }
360	    await fetch('/api/notes', {
361	      method: 'POST',
362	      headers: { 'Content-Type': 'application/json' },
363	      body: JSON.stringify({ targetType: 'project', targetId: project.id, text: noteText }),
364	    });
365	    setNoteText('');
366	    await loadNotes();
367	  }
368	
369	  async function loadTasks() {
370	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
371	    setTasks(await res.json());
372	  }
373	
374	  async function loadTags() {
375	    const [mine, all] = await Promise.all([
376	      fetch(`/api/projects/${project.id}/tags`).then((r) => r.json()),
377	      fetch('/api/tags').then((r) => r.json()),
378	    ]);
379	    setTags(mine);
380	    setAllTags(all);
381	  }
382	
383	  useEffect(() => {
384	    void load();
385	    void loadTasks();
386	    void loadTags();
387	    void loadNotes();
388	  }, [project.id]);
389	
390	  async function toggleTask(id: number) {
391	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
392	    await loadTasks();
393	  }
394	
395	  async function addTag(e: React.FormEvent) {
396	    e.preventDefault();
397	    if (!tagToAdd) {
398	      return;
399	    }
400	    await fetch(`/api/projects/${project.id}/tags`, {
401	      method: 'POST',
402	      headers: { 'Content-Type': 'application/json' },
403	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
404	    });
405	    setTagToAdd('');
406	    await loadTags();
407	  }
408	
409	  async function removeTag(id: number) {
410	    await fetch(`/api/projects/${project.id}/tags/${id}/remove`, { method: 'POST' });
411	    await loadTags();
412	  }
413	
414	  async function submit(e: React.FormEvent) {
415	    e.preventDefault();
416	    const value = Number(amount);
417	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
418	      setAmountError('Amount must be more than zero');
419	      return;
420	    }
421	    setAmountError('');
422	    await fetch('/api/invoices', {
423	      method: 'POST',
424	      headers: { 'Content-Type': 'application/json' },
425	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
426	    });
427	    setAmount('');
428	    await load();
429	  }
430	
431	  async function send(id: number) {
432	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
433	    await load();
434	  }
435	
436	  async function pay(id: number) {
437	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
438	    await load();
439	  }
440	
441	  const shownTasks = tasks.filter((t) =>
442	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
443	  );
444	
445	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
446	  const shownInvoices = sortByDue
447	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
448	    : invoices;
449	
450	  return (
451	    <section data-testid="project-detail">
452	      <h2 data-testid="project-detail-name">{project.name}</h2>
453	
454	      <section data-testid="project-budget-panel">
455	        <p data-testid="project-budget">
456	          {budget && budget.budget != null ? moneyGrouped(budget.budget) : ''}
457	        </p>
458	        <p data-testid="project-invoiced">{moneyGrouped(budget ? budget.invoiced : 0)}</p>
459	        <p data-testid="project-remaining">
460	          {budget && budget.remaining != null ? moneyGrouped(budget.remaining) : ''}
461	        </p>
462	        <form data-testid="project-budget-form" onSubmit={submitBudget}>
463	          <input
464	            data-testid="project-budget-input"
465	            placeholder="Budget"
466	            value={budgetInput}
467	            onChange={(e) => setBudgetInput(e.target.value)}
468	          />
469	          <button data-testid="project-budget-submit" type="submit">
470	            Set budget
471	          </button>
472	        </form>
473	      </section>
474	
475	      <div data-testid="project-tags">
476	        {tags.map((tag) => (
477	          <span key={tag.id}>
478	            <span data-testid={`project-tag-${tag.id}`}>{tag.name}</span>
